import {Chess} from './chess.js';
const $=id=>document.getElementById(id), names={p:'pawn',n:'knight',b:'bishop',r:'rook',q:'queen',k:'king'},symbols={p:'♟',n:'♞',b:'♝',r:'♜',q:'♛',k:'♚'},values={p:100,n:320,b:330,r:500,q:900,k:0};
let showThreats=true, hinted=null, reviewText='', completed=new Set(), practiceSnapshot=null;
let game=new Chess(),mode='play',selected=null,pending=null,last=null,timer=null,busy=false,lesson=0,puzzle=0,solved=false;
const lessons=[{name:'Make room to grow',piece:'♟',text:'Pawns move forward one square, or two from their starting square. They capture one square diagonally. Move the e-pawn to e4 to claim space in the center.',from:'e2',to:'e4'},{name:'Meet the knight',piece:'♞',text:'Knights move in an L: two squares in one direction, then one sideways. They can jump over pieces! Move the knight from g1 to f3.',from:'g1',to:'f3'},{name:'Open a diagonal',piece:'♝',text:'Bishops travel diagonally and cannot jump over pieces. With the e-pawn out of the way, move your bishop from f1 to c4.',fen:'rnbqkbnr/pppp1ppp/8/4p3/4P3/8/PPPP1PPP/RNBQKBNR w KQkq - 0 2',from:'f1',to:'c4'},{name:'Bring your king to safety',piece:'♚',text:'Castling moves the king two squares toward a rook; the rook hops beside it. The path must be clear and safe, and neither piece can have moved. Castle by moving e1 to g1.',fen:'rnbqk2r/pppp1ppp/5n2/2b1p3/2B1P3/5N2/PPPP1PPP/RNBQK2R w KQkq - 4 4',from:'e1',to:'g1'}];
const puzzles=[{name:'The last rank',fen:'6k1/5ppp/8/8/8/8/5PPP/4R1K1 w - - 0 1',text:'Black’s own pawns block its king. Find a rook move that gives checkmate.',hint:'Your rook can travel all the way up the e-file.'},{name:'Queen and king, together',fen:'7k/8/5KQ1/8/8/8/8/8 w - - 0 1',text:'Your king protects nearby squares. Find a queen move that leaves Black no escape.',hint:'Try bringing the queen next to the king, on g7.'}];
lessons.push({name:'Use your rook',piece:'♜',text:'Rooks travel in straight lines. Move your rook from a1 to a7 to capture the pawn. Capturing means taking an opponent’s piece off the board.',fen:'7k/p7/8/8/8/8/7P/R5K1 w - - 0 1',from:'a1',to:'a7'},{name:'Promote a pawn',piece:'♛',text:'When a pawn reaches the far edge, it becomes a queen, rook, bishop, or knight. Move a7 to a8 and choose your new piece.',fen:'7k/P7/8/8/8/8/8/6K1 w - - 0 1',from:'a7',to:'a8'});
$('move-dock').append($('preview'));
function coach(title,copy){$('coach-title').textContent=title;$('coach-copy').textContent=copy;}
function evaluate(g){if(g.isCheckmate())return g.turn()==='w'?-100000:100000; if(g.isDraw())return 0;let score=0;for(let row of g.board())for(let p of row)if(p){let f=p.square.charCodeAt(0)-97,r=+p.square[1];let center=(3.5-Math.abs(3.5-f))+(3.5-Math.abs(4.5-r));let bonus=p.type==='p'?(p.color==='w'?r-2:7-r)*8+center*4:['n','b'].includes(p.type)?center*12:0;score+=(p.color==='w'?1:-1)*(values[p.type]+bonus);}return score;}
function search(g,depth,alpha=-Infinity,beta=Infinity){if(!depth||g.isGameOver())return evaluate(g);let white=g.turn()==='w',best=white?-Infinity:Infinity;let moves=g.moves({verbose:true}).sort((a,b)=>(values[b.captured]||0)-(values[a.captured]||0));for(let m of moves){g.move(m);let score=search(g,depth-1,alpha,beta);g.undo();best=white?Math.max(best,score):Math.min(best,score);if(white)alpha=Math.max(alpha,best);else beta=Math.min(beta,best);if(beta<=alpha)break;}return best;}
function bestMove(g){let white=g.turn()==='w',best=white?-Infinity:Infinity,choice=null;for(let m of g.moves({verbose:true})){g.move(m);let score=search(g,1);g.undo();if((white&&score>best)||(!white&&score<best)){best=score;choice=m;}}return choice;}
function explain(m){let text=`Your ${names[m.piece]} moves from ${m.from} to ${m.to}. `;if(m.captured)text+=`It captures a ${names[m.captured]}. `;if(m.promotion)text+=`Your pawn becomes a ${names[m.promotion]}. `;if(m.flags.includes('k')||m.flags.includes('q'))text+='Castling tucks your king away and brings your rook closer to the action. ';else if(m.piece==='p'&&['d4','e4'].includes(m.to))text+='A center pawn controls useful squares and opens paths for your pieces. ';else if(['n','b'].includes(m.piece)&&['1','8'].includes(m.from[1]))text+='Developing a piece brings another helper into the game. ';let test=new Chess(game.fen());test.move(m);if(test.isCheckmate())text+='Checkmate! The king has no legal escape.';else if(test.isCheck())text+='This gives check: the opponent must protect their king. ';let exposed=test.board().flat().filter(p=>p&&p.color==='w'&&p.type!=='k'&&test.isAttacked(p.square,'b')&&!test.isAttacked(p.square,'w'));if(exposed.length)text+=`Unprotected and attacked: ${exposed.map(p=>names[p.type]+' on '+p.square).join(', ')}. `;if(test.isAttacked(m.to,'b')&&!test.isCheckmate())text+='Watch out: Black attacks this destination. Consider whether the piece is protected or the trade is worth it.';return text;}
function render(){let legal=selected?game.moves({square:selected,verbose:true}):[];$('board').innerHTML='';
for(let r=8;r>=1;r--)for(let f=0;f<8;f++){let sq=String.fromCharCode(97+f)+r,p=game.get(sq),b=document.createElement('button');b.className='square'+((f+r)%2===0?' dark':'')+(selected===sq?' selected':'')+(showThreats&&p?.color==='w'&&game.isAttacked(sq,'b')?' threatened':'')+(hinted?.to===sq?' hint-square':'')+(legal.some(m=>m.to===sq)?' legal':'')+(pending?.to===sq?' preview':'')+(last&&(last.from===sq||last.to===sq)?' last':'');b.setAttribute('aria-label',`${sq}${p?' '+(p.color==='w'?'white':'black')+' '+names[p.type]:', empty'}${legal.some(m=>m.to===sq)?', legal move':''}`);b.onclick=()=>{selectSquare(sq);[...$('board').children].find(x=>x.dataset.square===sq)?.focus({preventScroll:true});};b.dataset.square=sq;b.onkeydown=e=>{let directions={ArrowLeft:-1,ArrowRight:1,ArrowUp:-8,ArrowDown:8};if(e.key in directions){e.preventDefault();let squares=[...$('board').children],i=squares.indexOf(b),n=i+directions[e.key];if(n>=0&&n<64)squares[n].focus();}};if(p)b.innerHTML=`<span class="piece ${p.color==='w'?'white':'black'}" aria-hidden="true">${symbols[p.type]}</span>`;if(f===0)b.innerHTML+=`<span class="coord">${r}</span>`;if(r===1)b.innerHTML+=`<span class="coord file">${String.fromCharCode(97+f)}</span>`;if(showThreats&&p?.color==='w'&&game.isAttacked(sq,'b'))b.innerHTML+='<span class="danger-mark" aria-hidden="true">!</span>';$('board').append(b);}
$('preview').hidden=!pending;$('promotion-label').hidden=!pending?.promotion;$('undo').disabled=!game.history().length;$('hint').disabled=busy||game.isGameOver()||solved;$('confirm').disabled=busy;
let status=busy?'Partner is thinking…':game.isCheckmate()?'Checkmate · '+(game.turn()==='b'?'You won!':'A new lesson learned'):game.isStalemate()?'Draw · stalemate':game.isThreefoldRepetition()?'Draw · repeated position':game.isInsufficientMaterial()?'Draw · insufficient material':game.isDraw()?'Draw · 50-move rule':solved?'Nicely done! Choose your next challenge.':game.isCheck()?'Your king is in check · find a safe response':'Your turn · choose a white piece';$('status').textContent=status; $('board-guide').textContent=busy?'Your partner is thinking. Look for what changed on the board.':solved?'✓ You did it! Continue when you’re ready.':game.isGameOver()?status:pending?'③ Read the move preview below, then choose Play this move.':selected?`② Choose a dotted square for your ${names[game.get(selected).type]}.`:mode==='lessons'?lessons[lesson].text:mode==='puzzles'?puzzles[puzzle].text:'① Pick any white piece. Dots show its legal moves.'; $('next-step').hidden=!solved;$('next-step').textContent=mode==='lessons'?(lesson<lessons.length-1?'Next lesson →':'Put it into practice →'):'Next puzzle →'; $('review').hidden=!reviewText;$('review-copy').textContent=reviewText;
let hist=game.history({verbose:true});$('move-count').textContent=hist.length+' moves';$('history').innerHTML=hist.length?'':'<p class="empty">Your story starts with your first move.</p>';for(let i=hist.length-1;i>=0;i--){let m=hist[i];$('history').innerHTML+=`<div class="plain-move"><span>${m.color==='w'?'You':'Partner'}</span><div>${names[m.piece][0].toUpperCase()+names[m.piece].slice(1)} ${m.from} → ${m.to}${m.captured?' · captured '+names[m.captured]:''}${m.promotion?' · became '+names[m.promotion]:''}</div><small>${m.san}</small></div>`;}

}
function selectSquare(sq){if(busy||game.isGameOver()||solved)return;hinted=null;let p=game.get(sq);if(p?.color==='w'){selected=sq;pending=null;coach(`Meet your ${names[p.type]}.`,{p:'Pawns move straight forward and capture diagonally. On their first move, they can advance two squares.',n:'A knight moves in an L shape: two squares, then one to the side. It can jump over other pieces.',b:'A bishop moves any distance diagonally, until another piece blocks its path.',r:'A rook moves any distance along a row or column, until another piece blocks its path.',q:'The queen moves any distance along a row, column, or diagonal.',k:'The king moves one square in any direction, but can never move into an attack.'}[p.type]);render();return;}let m=selected&&game.moves({square:selected,verbose:true}).find(m=>m.to===sq);if(m){pending=m.promotion?{...m,promotion:'q'}:m;$('promotion').value='q';$('preview-text').textContent=explain(pending);coach('See the move before you make it.','Read the idea below. You can play it, or pick another piece.');render();if(matchMedia('(max-width:700px)').matches)$('move-dock').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'nearest'});}else{pending=null;selected=null;render();}}
function commit(){if(!pending||busy)return;let m={from:pending.from,to:pending.to,promotion:$('promotion').value};if(mode==='lessons'&&(m.from!==lessons[lesson].from||m.to!==lessons[lesson].to)){coach('A legal move. Try the lesson’s idea.',lessons[lesson].text);pending=null;selected=null;render();return;}let played=game.move(m);hinted=null;last=played;pending=null;selected=null;if(mode==='puzzles'){if(game.isCheckmate()){solved=true;coach('Checkmate. You found it!','Notice how your pieces work together to take away every escape. Try the next puzzle when you’re ready.');}else{let stalemate=game.isStalemate();game.undo();last=null;coach('Not quite checkmate. Try again.',stalemate?'The king needs to be in check, too.':puzzles[puzzle].text+' You can try as many times as you like.');}}else if(mode==='lessons'){solved=true;completed.add(lesson);activity();coach('That’s it. You’ve got the idea.',lesson===lessons.length-1?'Your pawn became a new piece. You’re ready to put these ideas into a practice game.':'A small idea you can use in every game. Choose the next lesson to keep going.');}else{coach('One move wiser.',explainAfter(played));if(!game.isGameOver()){busy=true;timer=setTimeout(()=>{let reply=bestMove(game);if(reply){game.move(reply);last=reply;const attacked=game.board().flat().filter(p=>p&&p.color==='w'&&p.type!=='k'&&game.isAttacked(p.square,'b')); reviewText=`You moved your ${names[played.piece]} from ${played.from} to ${played.to}. Black moved its ${names[reply.piece]} from ${reply.from} to ${reply.to}.${reply.captured?' Your '+names[reply.captured]+' was captured. Use Take back to explore another move.':''} ${attacked.length?'Look at your attacked '+attacked.map(p=>names[p.type]+' on '+p.square).join(', ')+'. Can you move, defend, or make a useful trade?':'None of your pieces is currently attacked. Look for a move that improves a piece or controls the center.'}`;coach(game.isCheck()?'Your king needs you.':'Your partner has replied.',`Black played ${reply.san}${reply.captured?', capturing your '+names[reply.captured]:''}. ${game.isCheck()?'Get out of check by moving the king, blocking the attack, or capturing the attacker.':'Before you move, ask: what is Black attacking, and is my king safe?'}`);}busy=false;endMessage();render();},450);}else endMessage();}render();}
function explainAfter(m){return `You played ${m.san}. Look at the squares your ${names[m.piece]} now controls. Your partner will reply next.`;}
function endMessage(){if(game.isCheckmate())coach(game.turn()==='b'?'Checkmate. Well played!':'Checkmate. Let’s learn from it.',game.turn()==='b'?'You left the opposing king with no legal escape. Start a fresh game to practice again.':'Use Take back to explore another response, or start a new game. Each attempt teaches you something.');else if(game.isDraw())coach('A shared result: a draw.','Neither player wins this game. The board status below tells you why. Start fresh to try again.');}
function start(nextMode=mode,resume=false){if(mode==='play'&&nextMode!=='play'){if(busy)game.undo();practiceSnapshot={pgn:game.pgn(),reviewText};}clearTimeout(timer);busy=false;mode=nextMode;selected=pending=last=null;solved=false;hinted=null;reviewText='';game=new Chess(mode==='lessons'?lessons[lesson].fen:mode==='puzzles'?puzzles[puzzle].fen:undefined);if(resume&&mode==='play'&&practiceSnapshot){game.loadPgn(practiceSnapshot.pgn);reviewText=practiceSnapshot.reviewText;}document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-pressed',String(b.dataset.mode===mode));});$('opponent-label').innerHTML=mode==='play'?'Your practice partner<small>A patient opponent, at your pace</small>':mode==='lessons'?'A little lesson<small>One idea. One move. All yours.</small>':'Your puzzle board<small>White to move · checkmate in one</small>';if(mode==='play')coach('Let’s find your first move.','Click a white piece. The dots show where it can go. Try moving a center pawn to give your other pieces room to join in.');else coach(mode==='lessons'?lessons[lesson].name:puzzles[puzzle].name,mode==='lessons'?lessons[lesson].text:puzzles[puzzle].text);activity();render();}
function activity(){let el=$('activity');if(mode==='play'){el.innerHTML='<div class="card-label">YOUR FIRST BIG IDEA</div><h3>Own a little of the center.</h3><p>The middle four squares are a crossroads. Controlling them gives your pieces more places to go.</p><button class="primary" id="start-lesson">Learn by doing <span>→</span></button>';$('start-lesson').onclick=()=>{lesson=0;start('lessons');};}else if(mode==='lessons'){el.innerHTML='<div class="card-label">'+completed.size+' / '+lessons.length+' LESSONS EXPLORED</div>'+lessons.map((l,i)=>`<button class="lesson-row ${lesson===i?'active':''}" data-lesson="${i}"><span>${l.piece}</span>${l.name}<span>${completed.has(i)?'✓':'0'+(i+1)}</span></button>`).join('');el.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{lesson=+b.dataset.lesson;start();});}else{el.innerHTML='<div class="card-label">THE CHECKMATE LAB</div><h3>One move can change everything.</h3><p>Checkmate means the king is attacked and has no legal way out. You have unlimited attempts.</p><div class="challenge-options">'+puzzles.map((p,i)=>`<button data-puzzle="${i}" class="${puzzle===i?'active':''}">Puzzle ${i+1}</button>`).join('')+'</div>';el.querySelectorAll('[data-puzzle]').forEach(b=>b.onclick=()=>{puzzle=+b.dataset.puzzle;start();});}}
$('confirm').onclick=commit;$('cancel').onclick=()=>{pending=null;selected=null;render();};$('promotion').onchange=()=>{if(pending){pending={...pending,promotion:$('promotion').value};$('preview-text').textContent=explain(pending);}};
$('undo').onclick=()=>{clearTimeout(timer);busy=false;if(game.history().length){game.undo();if(mode==='play'&&game.turn()==='b')game.undo();}solved=false;reviewText='';hinted=null;selected=pending=last=null;coach('A fresh look at the same moment.','Nothing lost. Try a different move and see how the position changes.');render();};$('restart').onclick=()=>start();$('hint').onclick=()=>{if(mode==='lessons'){selected=lessons[lesson].from;hinted=lessons[lesson];coach('Here’s your next small step.',lessons[lesson].text);}else if(mode==='puzzles'){hinted=puzzle===0?{from:'e1',to:'e8'}:{from:'g6',to:'g7'};selected=hinted.from;coach('A little nudge.',puzzles[puzzle].hint);}else{let m=bestMove(game);if(m){selected=m.from;hinted=m;coach(`Explore ${m.from} to ${m.to}.`,explain(m)+' This is a short-search suggestion, not a guarantee of the best move.');}}render();};document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{if(b.dataset.mode!==mode)start(b.dataset.mode,true);});$('help').onclick=()=>$('help-dialog').showModal();$('close-help').onclick=$('begin').onclick=()=>$('help-dialog').close();
$('show-threats').onchange=e=>{showThreats=e.target.checked;render();};$('next-step').onclick=()=>{if(mode==='lessons'){if(lesson<lessons.length-1){lesson++;start();}else start('play',true);}else {puzzle=(puzzle+1)%puzzles.length;start();}};
start();
if(document.modelContext?.registerTool){for(const tool of [{name:'read_chess_position',description:'Read the current board and legal moves.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({fen:game.fen(),mode,legalMoves:game.moves(),busy})},{name:'preview_chess_move',description:'Stage a legal white move for the learner to review and confirm. Does not play the move.',inputSchema:{type:'object',properties:{from:{type:'string'},to:{type:'string'}},required:['from','to'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(busy||solved||game.turn()!=='w'||!game.moves({verbose:true}).some(m=>m.from===input.from&&m.to===input.to))throw new Error('Move is not available.');selectSquare(input.from);selectSquare(input.to);return {staged:!!pending,from:pending?.from,to:pending?.to};}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}}}
